import numpy as np
def _cp(c, d):
    vs = c + np.sqrt(c*(c-d)); rho = 2.0*c - vs
    e1 = (vs-d)/(d-rho); e2 = (vs-c)/(c-rho)
    return np.array([vs, rho, e1, e2, 1.0-(e1/e2)**2])
params = _cp(-2.0, -1.0)
n = 0
def run_model():
    try:
        zolotarev_poles_nodes(params, n)
        return 0
    except ValueError:
        return 1
    except Exception:
        return 2
assert np.allclose(run_model(), target)

